use crate::aap::caps::{http_client, inference_llm};

struct Node;

const MAX_OVERVIEW: usize = 600;

fn percent_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

fn truncate(s: &str, max_bytes: usize) -> String {
    let mut out = String::new();
    for c in s.chars() {
        if out.len() + c.len_utf8() > max_bytes {
            break;
        }
        out.push(c);
    }
    out
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // Enrichment record: fetched on every call. The result is deliberately
        // ignored (a transport failure is a value, not an error), so the
        // node's output is unaffected.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&info.date)
        );
        let _ = http_client::fetch(&url);

        let mut prompt = format!("Date: {}\nItems:\n", info.date);
        for e in selected.entries.iter().filter(|e| e.kept) {
            prompt.push_str(&format!("- {} ({}): {}\n", e.title, e.feed, e.summary));
        }

        let system = "You write a short overview paragraph for a daily digest of \
                      selected feed items. Plain text, at most 500 characters.";
        let raw = inference_llm::infer(system, &prompt, "digest");

        let trimmed = raw.trim();
        let overview = if trimmed.is_empty() {
            truncate(
                &format!("Digest for {}: {} items.", info.date, selected.entries.len()),
                MAX_OVERVIEW,
            )
        } else {
            truncate(trimmed, MAX_OVERVIEW)
        };

        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
